<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/assets/css/app.css"><title>ماژول‌ها</title></head><body><header><b>✓ آزمون‌یار</b><nav><a href="/projects">پروژه‌ها</a><a href="/test-cases">سناریوها</a></nav></header><main class="app"><span><?=esc($project['code'])?></span><h1>درخت ماژول‌های <?=esc($project['name'])?></h1><?php if(session('message')):?><div class="alert"><?=esc(session('message'))?></div><?php endif ?><?php if(session('error')):?><div class="alert error"><?=esc(session('error'))?></div><?php endif ?><section><h2>افزودن ماژول یا زیربخش</h2><form method="post" class="grid"><label>نام ماژول<input name="name" required placeholder="مثلاً کاربران"></label><label>والد<select name="parent_id"><option value="">ریشه</option><?php foreach($nodes as $n):?><option value="<?=$n['id']?>"><?=esc($n['name'])?></option><?php endforeach?></select></label><button class="btn">افزودن</button></form></section><section><h2>ساختار فعلی</h2><table><tr><th>نام</th><th>نوع</th></tr><?php foreach($nodes as $n):?><tr><td><?= $n['parent_id']?'— ':'' ?><?=esc($n['name'])?></td><td><?= $n['parent_id']?'زیربخش':'ماژول اصلی' ?></td></tr><?php endforeach?></table></section></main></body></html>
